function layoutColliders(layout) {
  const out = [];
  const wallX = layout.wallX ?? DUNGEON_WALL_X;
  const endWallHw = layout.endWallHw ?? DUNGEON_END_WALL_HW;
  for (const sx of [-wallX, wallX]) {
    out.push({
      type: "obb",
      x: sx,
      z: layout.sideWallZ,
      hw: DUNGEON_WALL_HW,
      hd: layout.sideWallHd,
      rot: 0
    });
  }
  out.push({ type: "obb", x: 0, z: layout.zMax, hw: endWallHw, hd: DUNGEON_WALL_HW, rot: 0 });
  out.push({ type: "obb", x: 0, z: layout.zMin, hw: endWallHw, hd: DUNGEON_WALL_HW, rot: 0 });
  for (const s of layout.stubs)
    out.push({ type: "obb", x: s.x, z: s.z, hw: s.hw, hd: s.hd, rot: 0 });
  for (const p of layout.pillars)
    out.push({ type: "circle", x: p.x, z: p.z, r: PILLAR_COLLIDER_R });
  for (const t of layout.tombs)
    out.push({ type: "obb", x: t.x, z: t.z, hw: TOMB_HW, hd: TOMB_HD, rot: 0 });
  for (const c of layout.clutter ?? []) out.push({ type: "circle", x: c.x, z: c.z, r: 0.8 });
  return out;
}

// claudecraft-sim/delve_litany_layout.ts
var LITANY_Z_MIN = -19;
var LITANY_Z_MAX = 91;
var LITANY_WALL_X = 25;
var LITANY_DOOR_Z = -17;
var LITANY_MODULE_IDS = [
  "litany_sluice",
  "litany_ledger",
  "litany_ring",
  "litany_baptistry",
  "litany_choir_loft",
  "litany_causeway",
  "litany_apse"
];
function litanyRoom(def) {
  const wallX = def.wallX ?? LITANY_WALL_X;
  const zMin = def.zMin ?? LITANY_Z_MIN;
  const zMax = def.zMax ?? LITANY_Z_MAX;
  const pole = def.pole ?? { x: 0, z: (zMin + zMax) / 2 };
  return {
    bounds: { xMin: -wallX, xMax: wallX, zMin, zMax },
    doorZ: LITANY_DOOR_Z,
    ...def,
    wallX,
    zMin,
    zMax,
    pole
  };
}
function legacyRectShellColliders(geo) {
  const out = [];
  const sideZ = (geo.zMin + geo.zMax) / 2;
  const sideHd = (geo.zMax - geo.zMin) / 2;
  for (const sx of [-geo.wallX, geo.wallX]) {
    out.push({
      type: "obb",
      x: sx,
      z: sideZ,
      hw: DUNGEON_WALL_HW,
      hd: sideHd,
      rot: 0
    });
  }
  out.push({
    type: "obb",
    x: 0,
    z: geo.zMax,
    hw: DUNGEON_END_WALL_HW,
    hd: DUNGEON_WALL_HW,
    rot: 0
  });
  out.push({
    type: "obb",
    x: 0,
    z: geo.zMin,
    hw: DUNGEON_END_WALL_HW,
    hd: DUNGEON_WALL_HW,
    rot: 0
  });
  return out;
}
var WALL_SEGMENT_MAX = 6;
function polygonShellColliders(points) {
  const out = [];
  const n = points.length;
  for (let i = 0; i < n; i++) {
    const a = points[i];
    const b = points[(i + 1) % n];
    const dx = b.x - a.x;
    const dz = b.z - a.z;
    const len = Math.hypot(dx, dz);
    if (len < 1e-6) continue;
    const segCount = Math.max(1, Math.ceil(len / WALL_SEGMENT_MAX));
    const segLen = len / segCount;
    const rot = Math.atan2(-dz, dx);
    for (let s = 0; s < segCount; s++) {
      const midT = (s + 0.5) / segCount;
      out.push({
        type: "obb",
        x: a.x + dx * midT,
        z: a.z + dz * midT,
        hw: segLen / 2,
        hd: DUNGEON_WALL_HW,
        rot
      });
    }
  }
  return out;
}
function shellColliders(geo) {
  if (geo.walkable.length) return polygonShellColliders(geo.walkable[0].points);
  return legacyRectShellColliders(geo);
}
function interiorColliders(geo, includeHazards) {
  const out = [];
  for (const s of geo.stubs) out.push({ type: "obb", x: s.x, z: s.z, hw: s.hw, hd: s.hd, rot: 0 });
  for (const p of geo.pillars) out.push({ type: "circle", x: p.x, z: p.z, r: PILLAR_COLLIDER_R });
  for (const t of geo.tombs)
    out.push({ type: "obb", x: t.x, z: t.z, hw: TOMB_HW, hd: TOMB_HD, rot: 0 });
  for (const c of geo.clutter) out.push({ type: "circle", x: c.x, z: c.z, r: 0.8 });
  if (includeHazards) {
    for (const hz of geo.hazards) {
      if (!hz.blocksMovement) continue;
      out.push({ type: "circle", x: hz.x, z: hz.z, r: hz.rx ?? hz.r });
    }
  }
  return out;
}
