      id: "nythraxis_soul_rend",
      name: "Soul Rend",
      kind: "vulnerability",
      remaining: NYTHRAXIS_SOUL_REND_DURATION,
      duration: NYTHRAXIS_SOUL_REND_DURATION,
      value: 0,
      sourceId: boss.id,
      school: "shadow"
