    const share = Math.max(1, stacked);
    ctx.dealDamage(boss, p, Math.ceil(p.maxHp / share), false, "shadow", "Soul Rend", "hit", true);
    p.auras = p.auras.filter((a) => a.id !== "nythraxis_soul_rend");
