  player.castingAbility = "nythraxis_ward_channel";
  player.channeling = true;
  player.castTotal = NYTHRAXIS_DEATHLESS_CHANNEL;
  player.castRemaining = NYTHRAXIS_DEATHLESS_CHANNEL;
  player.castTargetId = null;
