// claudecraft-sim/leaderboard_page.ts
var LEADERBOARD_PAGE_SIZE = 50;
var LEADERBOARD_MAX = 1e3;
function paginateRanked(entries, requestedPage, requestedPageSize = LEADERBOARD_PAGE_SIZE) {
  const pageSize = Number.isFinite(requestedPageSize) ? Math.max(1, Math.min(LEADERBOARD_PAGE_SIZE * 2, Math.floor(requestedPageSize))) : LEADERBOARD_PAGE_SIZE;
  const total = Math.min(entries.length, LEADERBOARD_MAX);
  const pageCount = Math.max(1, Math.ceil(total / pageSize));
  const requested = Number.isFinite(requestedPage) ? Math.floor(requestedPage) : 0;
  const page = Math.max(0, Math.min(pageCount - 1, requested));
  const start = page * pageSize;
  const end = Math.min(total, start + pageSize);
  return {
    leaders: entries.slice(start, end),
    page,
    pageCount,
    total,
    pageSize
  };
}
function paginateLeaderboard(entries, requestedPage, requestedPageSize = LEADERBOARD_PAGE_SIZE) {
  return paginateRanked(entries, requestedPage, requestedPageSize);
}
function paginateGuildLeaderboard(entries, requestedPage, requestedPageSize = LEADERBOARD_PAGE_SIZE) {
  return paginateRanked(entries, requestedPage, requestedPageSize);
}
function paginateDevLeaderboard(entries, requestedPage, requestedPageSize = LEADERBOARD_PAGE_SIZE) {
  return paginateRanked(entries, requestedPage, requestedPageSize);
}

