  refreshKnownAbilities(meta, announce) {
    const e = this.entities.get(meta.entityId);
    if (!e) return;
    const before = new Map(meta.known.map((k) => [k.def.id, k.rank]));
    meta.known = abilitiesKnownAt(meta.cls, e.level, meta.talentMods);
    if (announce) {
      for (const k of meta.known) {
        const prev = before.get(k.def.id);
        if (prev === void 0 || prev < k.rank) {
          this.emit({
            type: "learnAbility",
            abilityId: k.def.id,
            rank: k.rank,
            pid: meta.entityId
          });
          this.emit({
            type: "log",
            pid: meta.entityId,
            text: prev === void 0 ? `You have learned a new ability: ${k.def.name}.` : `Your ${k.def.name} has improved to Rank ${k.rank}.`,
            color: "#ffd100"
          });
        }
      }
    }
  }
